CREATE ROLE authenticated;
CREATE ROLE anon;
CREATE ROLE service_role BYPASSRLS;
CREATE SCHEMA erp_private;
CREATE SCHEMA auth;
CREATE SCHEMA storage;
CREATE TABLE public.user_profiles(id bigint primary key,auth_user_id uuid unique,status text,must_change_password boolean,owner_company_id bigint,branch_id bigint,display_name text,full_name text,job_title text,avatar_url text);
CREATE TABLE public.roles(id bigint primary key,role_code text,is_active boolean,is_system_role boolean);
CREATE TABLE public.user_roles(id bigint generated by default as identity primary key,user_profile_id bigint,role_id bigint,owner_company_id bigint,branch_id bigint,is_active boolean);
CREATE TABLE public.owner_companies(id bigint primary key,status text,legal_name_en text);
CREATE TABLE public.branches(id bigint primary key,status text,owner_company_id bigint,branch_name_en text);
CREATE TABLE storage.buckets(id text primary key,name text,public boolean,file_size_limit bigint,allowed_mime_types text[]);
CREATE TABLE storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text,name text,metadata jsonb);
ALTER TABLE storage.objects ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT lpad(current_setting('test.actor',true),32,'0')::uuid $$;
CREATE FUNCTION auth.jwt() RETURNS jsonb LANGUAGE sql STABLE AS $$ SELECT jsonb_build_object('session_id',auth.uid()) $$;
CREATE FUNCTION public.f03_current_session_valid() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT auth.uid() IS NOT NULL AND current_setting('test.actor',true)<>'7' $$;
CREATE FUNCTION erp_private.business_principal_is_active() RETURNS boolean LANGUAGE sql STABLE AS $$ SELECT public.f03_current_session_valid() AND EXISTS(SELECT FROM public.user_profiles WHERE auth_user_id=auth.uid() AND status='active' AND NOT must_change_password) $$;
CREATE FUNCTION erp_private.provider_actor_session_valid(bigint,uuid) RETURNS boolean LANGUAGE sql AS $$ SELECT $2=lpad($1::text,32,'0')::uuid AND $1<>7 $$;
